import { z } from 'zod';

const Enquiry = z.object({
  name: z.string().trim().min(1).max(80),
  email: z.string().email(),
  budget: z.enum(['<50k', '50k-2L', '2L+']),
});

export async function POST(request: Request) {
  const parsed = Enquiry.safeParse(await request.json());
  if (!parsed.success) {
    return Response.json({ errors: parsed.error.flatten().fieldErrors }, { status: 400 });
  }
  // parsed.data is now trusted
}

CREATE TABLE project_members (
  project_id uuid REFERENCES projects(id) ON DELETE CASCADE,
  member_id  uuid REFERENCES members(id)  ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('lead', 'support')),
  PRIMARY KEY (project_id, member_id)
);

